@import url("chrome://messenger/skin/icons.css");
@import url("chrome://messenger/skin/colors.css");
@import url("chrome://messenger/skin/variables.css");

body {
  /* Override the absolute (px) font-size value in common-shared.css. */
  font-size: 1.1rem;
}

.sticky-container,
.main-search,
.main-heading {
  background: var(--layout-background-0);
  /* Nova overrides */
  --button-background-color: transparent;
  --button-background-color-ghost: transparent;
  --button-background-color-ghost-hover: var(--button-background-color-hover);
  --button-background-color-ghost-active: var(--button-background-color-active);
  --button-border-color-ghost: var(--button-border-color);
  --button-border-color-ghost-hover: var(--button-border-color-hover);
  --button-border-color-ghost-active: var(--button-border-color-active);
  --button-icon-fill: color-mix(in srgb, currentColor 20%, transparent);
  --button-icon-stroke: currentColor;
}
